-- Generated by Murakumo: load open_meteo.weather_daily (incremental), without Murakumo. Run it from the project folder.

-- The files under landing/open_meteo/weather_daily/ that were not loaded before.
create or replace temp table new_rows as
select cast(location_key as VARCHAR) as location_key, cast(latitude as DECIMAL(9,6)) as latitude, cast(longitude as DECIMAL(9,6)) as longitude, cast(timezone as VARCHAR) as timezone, cast(observed_date as DATE) as observed_date, cast(temperature_2m_max as DECIMAL(5,1)) as temperature_2m_max, cast(temperature_2m_min as DECIMAL(5,1)) as temperature_2m_min, cast(precipitation_sum as DECIMAL(6,1)) as precipitation_sum, cast(snowfall_sum as DECIMAL(6,2)) as snowfall_sum, cast(weather_code as INTEGER) as weather_code, filename
from read_json('landing/open_meteo/weather_daily/weather_daily_*.jsonl', format = 'newline_delimited', filename = true, columns = {'location_key': 'VARCHAR', 'latitude': 'DECIMAL(9,6)', 'longitude': 'DECIMAL(9,6)', 'timezone': 'VARCHAR', 'observed_date': 'DATE', 'temperature_2m_max': 'DECIMAL(5,1)', 'temperature_2m_min': 'DECIMAL(5,1)', 'precipitation_sum': 'DECIMAL(6,1)', 'snowfall_sum': 'DECIMAL(6,2)', 'weather_code': 'INTEGER'})
where parse_filename(filename) not in (select parse_filename(path) from audit.loaded_files where table_name = 'weather_daily');
-- Incremental: the new rows replace the rows with the same key; the latest of each key is kept.
delete from raw_open_meteo.weather_daily where (location_key, observed_date) in (select location_key, observed_date from new_rows);
insert into raw_open_meteo.weather_daily (location_key, latitude, longitude, timezone, observed_date, temperature_2m_max, temperature_2m_min, precipitation_sum, snowfall_sum, weather_code, _ingested_at, _batch_id)
select location_key, latitude, longitude, timezone, observed_date, temperature_2m_max, temperature_2m_min, precipitation_sum, snowfall_sum, weather_code, now(), parse_filename(filename) from new_rows
qualify row_number() over (partition by location_key, observed_date order by observed_date desc nulls last) = 1;
-- Remember the files, so the next run skips them.
insert into audit.loaded_files (table_name, path, size, sha256, rows_ingested, batch_id, loaded_at)
select 'weather_daily', filename, null, null, count(*), parse_filename(filename), now()
from new_rows group by filename;
drop table new_rows;
